 "content": "def transform(grid):
    """Extend each interior clue with the border sequence containing its color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Nonzero runs on the top and bottom borders are the sequence templates.
    templates = []
    for edge_row in {0, h - 1}:
        c = 0
        while c < w:
            if grid[edge_row][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[edge_row][c] != 0:
                c += 1
            templates.append(grid[edge_row][start:c])

    # A clue's color identifies its position within a template. Place one full
    # copy of that template on the clue's row, clipping at grid boundaries.
    for r in range(1, h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            match = next(((seq, seq.index(color)) for seq in templates if color in seq), None)
            if match is None:
                continue
            seq, index = match
            left = c - index
            for i, value in enumerate(seq):
                x = left + i
                if 0 <= x < w:
                    out[r][x] = value
    return out


